ote(q.state) AS BLOB))),0) FROM item_health q WHERE q.user_id=NEW.user_id)+(SELECT COUNT(*)*2048 FROM object_storage WHERE user_id=NEW.user_id),(SELECT COALESCE(SUM(bytes),0) FROM object_storage WHERE user_id=NEW.user_id) WHERE NOT EXISTS(SELECT 1 FROM storage_usage WHERE user_id=NEW.user_id); UPDATE storage_usage SET metadata_bytes=metadata_bytes+(2048+length(CAST(json_quote(NEW.id) AS BLOB))+length(CAST(json_quote(NEW.user_id) AS BLOB))+length(CAST(json_quote(NEW.url) AS BLOB))+length(CAST(json_quote(NEW.title) AS BLOB))+length(CAST(json_quote(NEW.note) AS BLOB))+length(CAST(json_quote(NEW.tags) AS BLOB))+length(CAST(json_quote(NEW.collection) AS BLOB))+length(CAST(json_quote(NEW.status) AS BLOB))+length(CAST(json_quote(NEW.kind) AS BLOB))+length(CAST(json_quote(NEW.file_key) AS BLOB))+length(CAST(json_quote(NEW.file_name) AS BLOB))+length(CAST(json_quote(NEW.file_type) AS BLOB))+length(CAST(json_quote(NEW.image) AS BLOB))+length(CAST(json_quote(NEW.body) AS BLOB))+length(CAST(json_quote(NEW.language) AS BLOB))) WHERE user_id=NEW.user_id AND changes()=0; SELECT CASE WHEN metadata_bytes>33554432 THEN RAISE(ABORT,'Account content storage limit reached') END FROM storage_usage WHERE user_id=NEW.user_id; END;
